using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Media;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.Calibration;
static class Program {
 static int checks;static void Check(bool b,string m){if(!b)throw new Exception(m);Console.WriteLine($"PASS {++checks}: {m}");}static JsonElement J<T>(T x)=>JsonSerializer.SerializeToElement(x);
 [STAThread]static int Main(){try{
 _=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var dir=Path.GetFullPath("analysis/rotate-calibration/path-checks");Directory.CreateDirectory(dir);var path=Path.Combine(dir,"matrix.iwcal");void Write(float x)=>File.WriteAllBytes(path,new float[]{x,0,10,0,2,-5,0,0,1}.SelectMany(BitConverter.GetBytes).ToArray());Write(2);
 var plugin=new RotateCalibrationPlugin();var backing=plugin.Descriptor.Parameters.ToDictionary(x=>x.Name,x=>x.DefaultValue!.Value.Clone());backing["FilePath"]=J(path);backing["InputWay"]=J(1);
 var input=new Dictionary<string,PortValue>{{"ImagePointX",PortValue.Number(50)},{"ImagePointY",PortValue.Number(40)},{"WorldRotateAngle",PortValue.Number(17)},{"RotNum",PortValue.Integer(3)}};
 var result=plugin.CreateRuntime().ExecuteAsync(new("rotate",dir,input,backing),CancellationToken.None).Result;Check(result.NativeErrorCode==0,"seed actual production sample");
 var state=typeof(RotateCalibrationPlugin).GetMethod("Get",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(plugin,["rotate",dir,null])!;var session=(RotateCalibrationSession)state.GetType().GetField("Session")!.GetValue(state)!;
 int applies=0;Action? onApply=null;var notices=new Notices();var picker=new Picker();var context=new ToolEditorContext(new("rotate",RotateCalibrationPlugin.Id,"1","rotate",backing),dir,next=>{applies++;backing=next;onApply?.Invoke();},_=>throw new Exception("unexpected pre-run")){ReadEffectiveParameters=()=>backing,ConfigurationNotifications=notices,ConfigurationFiles=picker};using var editor=plugin.CreateConfiguration(context);var node=editor.State.Find("FilePath")!;
 foreach(var invalid in new[]{"",Path.Combine(dir,"bad.IWCAL"),Path.Combine(dir,"missing-parent","bad.iwcal")}){int before=applies,count=notices.Items.Count;editor.State.CommitUser(node,invalid,true);Check(applies==before,"front-end rejects without adapter write: "+invalid);Check(node.Value==invalid&&editor.State.IsRejectedParameterWrite(node),"attempt remains model value");Check(session.Loaded&&session.Current==1&&session.FilePath==path,"front-end rejection preserves backend sample/cache/path");Check(notices.Items.Count==count+1&&notices.Items[^1].Kind==ConfigurationNotificationKind.Error,"one source error notification");}
 var cc=(ToolConfigurationControlContext)Activator.CreateInstance(typeof(ToolConfigurationControlContext),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{editor.State,node,(Func<Window?>)(()=>null)},null)!;Check(editor.Controls.TryCreate("OpenFileForCalibDialog",cc,out var control),"real Rotate path control factory");control!.Measure(new Size(400,100));control.Arrange(new Rect(0,0,400,100));control.UpdateLayout();var choose=Walk(control).OfType<System.Windows.Controls.Button>().Single(x=>x.Name=="ChooseCalibrationPath");picker.Selected=Path.Combine(dir,"bad.IWCAL");for(int i=1;i<=2;i++){int writes=applies,notifications=notices.Items.Count;choose.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Check(picker.History==i&&applies==writes&&notices.Items.Count==notifications+1,"same invalid picker forces error then unconditional history "+i);}
 var missing=Path.Combine(dir,"missing.iwcal");File.Delete(missing);int failedNotices=notices.Items.Count;editor.State.CommitUser(node,missing,true);Check(backing["FilePath"].GetString()==missing&&session.FilePath==missing,"valid directory failed load commits actual attempted path");Check(!session.Loaded&&session.Current==1,"failed backend load keeps samples but invalidates loaded matrix");Check(notices.Items.Count==failedNotices+1&&notices.Items[^1].Kind==ConfigurationNotificationKind.Error,"backend failed load reports exactly one error through Attach");Check(node.Value==missing&&editor.State.IsRejectedParameterWrite(node),"backend failure retained and not reported successful");
 Write(3);int successNotices=notices.Items.Count;onApply=()=>Write(4);editor.State.CommitUser(node,path,true);Check(session.Loaded&&session.Matrix[0]==3,"load before host apply, no duplicate adapter load");Check(notices.Items.Count==successNotices+1&&notices.Items[^1].Kind==ConfigurationNotificationKind.Success,"successful explicit load reports exactly one success through Attach");Check(!editor.State.IsRejectedParameterWrite(node),"recovery clears rejected marker");Write(5);onApply=()=>Write(6);editor.State.CommitUser(node,path,true);Check(session.Matrix[0]==5,"same-path forced commit reloads exactly once");Check(session.Current==1,"explicit reload preserves collected sample");Console.WriteLine($"PASS {checks}: Rotate production path lifecycle");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static IEnumerable<DependencyObject> Walk(DependencyObject x){yield return x;for(int i=0;i<VisualTreeHelper.GetChildrenCount(x);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(x,i)))yield return child;}
 sealed class Picker:IToolConfigurationFileService{public string Selected="";public int History;public ConfigurationFileSelection Select(Window? owner,ConfigurationFileRequest request)=>new(ConfigurationFileStatus.Selected,[Selected]);public ConfigurationFileHistoryResult Remember(string moduleKey,string path){History++;return new(true,Path.GetDirectoryName(path));}}
 sealed class Notices:IToolConfigurationNotificationService{public List<ConfigurationNotification> Items=[];public ConfigurationNotificationResult Notify(Window? owner,ConfigurationNotification n){Items.Add(n);return new(ConfigurationNotificationStatus.Displayed);}}
}
